const OWNER = '.claude/rules/backend-tests/test-framework.md';
// Test frameworks other than NUnit; introducing one needs a concrete reason.
const OTHER_FRAMEWORKS = /^(xunit(\.v3)?|xunit\.core|mstest|mstest\.testframework|mstest\.testadapter|tunit)$/i;

function checkProject(ctx, project) {
  if (ctx.roleOf(project.name).kind !== 'test') return [];
  return project.packages
    .filter(pkg => OTHER_FRAMEWORKS.test(pkg.id))
    .map(pkg => lib.finding('warn', project.rel, `test project uses "${pkg.id}" in addition to or instead of NUnit`, OWNER));
}

function checkCentralPackages(ctx, rel, packages) {
  return packages
    .filter(pkg => OTHER_FRAMEWORKS.test(pkg.id))
    .map(pkg => lib.finding('warn', rel, `central version for additional test framework "${pkg.id}"`, OWNER));
}

Arrange/Act/Assert is a useful default; comments are optional when the phases are obvious. Use the constraint model (`Assert.That(actual, Is...)`).

## Explicit case tables

Explicit cases (rule: `.claude/rules/backend-tests/testing.md`) are written as `[TestCase]` rows with the expected value as an argument, rather than `TestCaseSource` generators or computed expectations. A longer explicit table beats a shorter algorithmic test when it makes the business rules visible:

```csharp
[TestCase(TaskStatus.Created, TaskStatus.InProgress, true)]
[TestCase(TaskStatus.Created, TaskStatus.Completed, false)]
[TestCase(TaskStatus.InProgress, TaskStatus.Completed, true)]
public void IsTransitionAllowed_ReturnsExpected(TaskStatus current, TaskStatus target, bool expected)
{
    var actual = TaskWorkflowRules.IsTransitionAllowed(current, target);

    Assert.That(actual, Is.EqualTo(expected));
}
```

Prefer one observable scenario per test; multi-step tests fit when the sequence itself is the scenario (an entire workflow or a replace-set lifecycle).

function stop(input) {
  if (input.stop_hook_active) return 0; // never re-block a continuation triggered by this hook
  const cochange = require('../scripts/check-cochange.cjs');
  const result = cochange.run(lib.activeRoot(workingDirectory(input)), 'hook');
  if (!result.applicable) {
    process.stdout.write(`${JSON.stringify({ systemMessage: 'Co-change reminders inactive: the project is not a Git work tree.' })}\n`);
    return 0;
  }
  if (!result.reminders.length) return 0;
  process.stderr.write(
    `Co-change reminders (reported once per content state):\n${cochange.format(result.reminders)}\n` +
    'Address each item or state why it does not apply, then finish.\n');
  return 2;
}

/** Framework-neutral reminder: backend production code changed without any backend test change. */
function testReminder(changes) {
  const isBackendCs = p => p.startsWith('backend/') && p.endsWith('.cs');
  const isTest = p => /^backend\/[^/]*Tests?\//.test(p);
  const production = changes.filter(c => isBackendCs(c.path) && !isTest(c.path) && !c.status.includes('D'));
  if (!production.length || changes.some(c => isTest(c.path))) return [];
  return [{
    id: 'tests',
    message: `backend production code changed (${production.length} file(s)) with no backend test change; confirm coverage and probe preservation`,
    owner: 'verify workflow (step 4), development-workflow (bug fixes)',
    paths: production.map(c => c.path),
  }];
}

